import hashlib
import hmac
import json
import os
import time
import secrets
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs
import threading

SECRET_KEY = os.environ.get('APP_SECRET', secrets.token_hex(32))
ADMIN_PASSWORD_HASH = os.environ.get('ADMIN_HASH', '')

# Role-Based Access Control System
class RBACEngine:
    def __init__(self):
        self._roles = {}
        self._user_roles = {}
        self._role_hierarchy = {}  # child -> parent
        self._setup_default_roles()

    def _setup_default_roles(self):
        # Define roles with permissions: (action, resource) -> allow/deny
        self._roles['viewer'] = {
            'allows': [('read', '/public/*'), ('read', '/docs/*')],
            'denies': []
        }
        self._roles['editor'] = {
            'allows': [('read', '/public/*'), ('read', '/docs/*'), ('write', '/docs/*')],
            'denies': [('write', '/docs/readonly/*')]
        }
        self._roles['admin'] = {
            'allows': [('read', '*'), ('write', '*'), ('delete', '*')],
            'denies': []
        }
        self._roles['restricted_editor'] = {
            'allows': [('write', '/docs/drafts/*')],
            'denies': []
        }
        # Hierarchy: restricted_editor inherits from editor
        self._role_hierarchy['restricted_editor'] = 'editor'

        # Default users
        self._user_roles['alice'] = ['admin']
        self._user_roles['bob'] = ['restricted_editor']
        self._user_roles['charlie'] = ['viewer']

    def _match_resource(self, pattern, resource):
        """Match a resource against a pattern with wildcard support."""
        if pattern == '*':
            return True
        if pattern.endswith('/*'):
            prefix = pattern[:-1]  # Keep the trailing slash
            return resource.startswith(prefix) or resource == prefix[:-1]
        return pattern == resource

    def _get_effective_permissions(self, role_name, visited=None):
        """Get all permissions for a role including inherited ones.

        Inheritance model: child role's explicit allows take precedence
        over parent's denies for the SAME resource. Parent denies are
        only inherited if the child doesn't have an explicit allow
        for that specific resource pattern.
        """
        if visited is None:
            visited = set()
        if role_name in visited:
            return {'allows': [], 'denies': []}
        visited.add(role_name)

        role = self._roles.get(role_name)
        if not role:
            return {'allows': [], 'denies': []}

        effective = {
            'allows': list(role['allows']),
            'denies': list(role['denies'])
        }

        # Inherit from parent
        parent = self._role_hierarchy.get(role_name)
        if parent:
            parent_perms = self._get_effective_permissions(parent, visited)
            # Add parent allows that child doesn't already have
            for perm in parent_perms['allows']:
                if perm not in effective['allows']:
                    effective['allows'].append(perm)
            # Only inherit parent denies if child has NO explicit allow
            # that covers the same action (not resource-specific check)
            child_allow_actions = set(a for a, r in role['allows'])
            for deny_action, deny_resource in parent_perms['denies']:
                if deny_action not in child_allow_actions:
                    effective['denies'].append((deny_action, deny_resource))

        return effective

    def check_permission(self, username, action, resource):
        """Check if a user has permission to perform an action on a resource.

        Evaluation order:
        1. Collect all effective permissions from all user roles
        2. If any deny matches -> DENY
        3. If any allow matches -> ALLOW
        4. Default -> DENY
        """
        roles = self._user_roles.get(username, [])
        if not roles:
            return False

        all_allows = []
        all_denies = []

        for role_name in roles:
            perms = self._get_effective_permissions(role_name)
            all_allows.extend(perms['allows'])
            all_denies.extend(perms['denies'])

        # Check denies first
        for deny_action, deny_resource in all_denies:
            if deny_action == action and self._match_resource(deny_resource, resource):
                return False

        # Check allows
        for allow_action, allow_resource in all_allows:
            if allow_action == action and self._match_resource(allow_resource, resource):
                return True

        return False


rbac = RBACEngine()
data_store = {}
data_lock = threading.Lock()


def generate_token(username):
    payload = f"{username}:{int(time.time())}"
    sig = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}:{sig}"


def verify_token(token):
    if not token or ':' not in token:
        return None
    parts = token.rsplit(':', 1)
    if len(parts) != 2:
        return None
    payload, sig = parts
    expected = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(sig, expected):
        return None
    payload_parts = payload.split(':', 1)
    if len(payload_parts) != 2:
        return None
    username, ts_str = payload_parts
    try:
        issued_at = int(ts_str)
    except ValueError:
        return None
    now = int(time.time())
    if now - issued_at > 3600 or issued_at > now + 60:
        return None
    return username


class AppHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        parsed = urlparse(self.path)
        if parsed.path == '/login':
            self._handle_login(parse_qs(parsed.query))
        elif parsed.path.startswith('/api/data/'):
            self._handle_read(parsed.path)
        else:
            self._send_response(404, {'error': 'not found'})

    def do_POST(self):
        parsed = urlparse(self.path)
        if parsed.path.startswith('/api/data/'):
            self._handle_write(parsed.path)
        else:
            self._send_response(404, {'error': 'not found'})

    def do_DELETE(self):
        parsed = urlparse(self.path)
        if parsed.path.startswith('/api/data/'):
            self._handle_delete(parsed.path)
        else:
            self._send_response(404, {'error': 'not found'})

    def _get_user(self):
        auth = self.headers.get('Authorization', '')
        if not auth.startswith('Bearer '):
            return None
        return verify_token(auth[7:])

    def _handle_login(self, params):
        username = params.get('user', [''])[0]
        if username in rbac._user_roles:
            token = generate_token(username)
            self._send_response(200, {'token': token})
        else:
            self._send_response(401, {'error': 'unknown user'})

    def _handle_read(self, path):
        user = self._get_user()
        if not user:
            self._send_response(401, {'error': 'unauthorized'})
            return
        resource = path[len('/api/data'):]
        if not rbac.check_permission(user, 'read', resource):
            self._send_response(403, {'error': 'forbidden'})
            return
        with data_lock:
            value = data_store.get(resource, None)
        if value is None:
            self._send_response(404, {'error': 'not found'})
        else:
            self._send_response(200, {'resource': resource, 'value': value})

    def _handle_write(self, path):
        user = self._get_user()
        if not user:
            self._send_response(401, {'error': 'unauthorized'})
            return
        resource = path[len('/api/data'):]
        if not rbac.check_permission(user, 'write', resource):
            self._send_response(403, {'error': 'forbidden'})
            return
        content_length = int(self.headers.get('Content-Length', 0))
        body = self.rfile.read(content_length)
        try:
            data = json.loads(body)
        except (json.JSONDecodeError, UnicodeDecodeError):
            self._send_response(400, {'error': 'invalid json'})
            return
        with data_lock:
            data_store[resource] = data
        self._send_response(200, {'status': 'written', 'resource': resource})

    def _handle_delete(self, path):
        user = self._get_user()
        if not user:
            self._send_response(401, {'error': 'unauthorized'})
            return
        resource = path[len('/api/data'):]
        if not rbac.check_permission(user, 'delete', resource):
            self._send_response(403, {'error': 'forbidden'})
            return
        with data_lock:
            data_store.pop(resource, None)
        self._send_response(200, {'status': 'deleted', 'resource': resource})

    def _send_response(self, code, body):
        self.send_response(code)
        self.send_header('Content-Type', 'application/json')
        resp = json.dumps(body).encode()
        self.send_header('Content-Length', str(len(resp)))
        self.end_headers()
        self.wfile.write(resp)

    def log_message(self, format, *args):
        pass


if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), AppHandler)
    server.serve_forever()
